    t = parse_time_of_day(time_of_day)

    year = now.year
    month = now.month

    for _ in range(0, 2):
        try:
            candidate = datetime(year, month, day_of_month, t.hour, t.minute)
            if candidate > now:
                return candidate
        except ValueError:
            pass

