    return None

def build_tencent_symbol(code: str, market: str) -> str:
    """构建腾讯财经 API 的股票符号"""
    code = clean_code(code)
    if market == "sh":
        return f"sh{code}"
    elif market == "sz":
        return f"sz{code}"
    elif market == "hk":
        # 港股指数（纯字母如 HSI、HSCEI）不需要补零
